function ThreadToolbar({ thread }: { thread: Thread }) {
  const closeThread = useMail((s) => s.closeThread);
  const archive = useMail((s) => s.archive);
  const moveToTrash = useMail((s) => s.moveToTrash);
  const markRead = useMail((s) => s.markRead);
  const reportSpam = useMail((s) => s.reportSpam);
  const moveToInbox = useMail((s) => s.moveToInbox);
  const deleteForever = useMail((s) => s.deleteForever);
  const [menu, setMenu] = useState<null | 'snooze' | 'labels' | 'more'>(null);
  const id = [thread.id];
  const inTrash = thread.labels.includes('TRASH');
  const inSpam = thread.labels.includes('SPAM');

  return (
    <div className="toolbar thread-toolbar" role="toolbar" aria-label="Conversation actions">
      <button className="icon-btn" aria-label="Back to list" title="Back (u)" onClick={closeThread}>
        <Icon name="back" />
      </button>
      {!inTrash && (
        <button className="icon-btn" aria-label="Archive" title="Archive (e)" onClick={() => archive(id)}>
          <Icon name="archive" />
        </button>
      )}
      {!inTrash && !inSpam && (
        <button className="icon-btn" aria-label="Report spam" title="Report spam" onClick={() => reportSpam(id, true)}>
          <Icon name="spam" />
        </button>
      )}
      <button
        className="icon-btn"
        aria-label={inTrash ? 'Delete forever' : 'Delete'}
        title={inTrash ? 'Delete forever' : 'Delete (#)'}
        onClick={() => (inTrash ? deleteForever(id) : moveToTrash(id))}
      >
        <Icon name="trash" />
      </button>
      <span className="toolbar-sep" />
      <button className="icon-btn" aria-label="Mark as unread" title="Mark as unread (⇧U)" onClick={() => { markRead(id, false); closeThread(); }}>
        <Icon name="mailUnread" />
      </button>
      {!inTrash && (
        <div className="menu-anchor">
          <button className="icon-btn" aria-label="Snooze" title="Snooze (b)" onClick={() => setMenu(menu === 'snooze' ? null : 'snooze')}>
            <Icon name="snooze" />
          </button>
          <Popover open={menu === 'snooze'} onClose={() => setMenu(null)} className="menu-pop" width={240}>
            <SnoozeMenu ids={id} onDone={() => setMenu(null)} />
          </Popover>
        </div>
      )}
      <div className="menu-anchor">
        <button className="icon-btn" aria-label="Labels" title="Labels (l)" onClick={() => setMenu(menu === 'labels' ? null : 'labels')}>
          <Icon name="label" />
        </button>
        <Popover open={menu === 'labels'} onClose={() => setMenu(null)} className="menu-pop" width={220}>
          <LabelsMenu ids={id} onDone={() => setMenu(null)} />
        </Popover>
      </div>
      <div className="menu-anchor">
        <button className="icon-btn" aria-label="More" title="More" onClick={() => setMenu(menu === 'more' ? null : 'more')}>
          <Icon name="more" />
        </button>
        <Popover open={menu === 'more'} onClose={() => setMenu(null)} className="menu-pop">
          {(inTrash || inSpam) && (
            <button className="menu-item" onClick={() => { moveToInbox(id); setMenu(null); }}>
              <Icon name="inbox" size={16} /> Move to Inbox
            </button>
          )}
          {inSpam && (
            <button className="menu-item" onClick={() => { reportSpam(id, false); setMenu(null); }}>
              <Icon name="spam" size={16} /> Not spam
            </button>
          )}
          {inTrash && (
            <button className="menu-item danger" onClick={() => { deleteForever(id); setMenu(null); }}>
              <Icon name="trash" size={16} /> Delete forever
            </button>
          )}
          <button className="menu-item" onClick={() => { setMenu(null); useMail.getState().openForward(thread); }}>
            <Icon name="forward" size={16} /> Forward
          </button>
        </Popover>
      </div>
    </div>
  );
}

export function ThreadView({ thread }: { thread: Thread }) {
  const labels = useMail((s) => s.labels);
  const applyLabel = useMail((s) => s.applyLabel);
  const [expandedIds, setExpandedIds] = useState<Set<string>>(new Set());
  const customLabels = labels.filter((l) => thread.labels.includes(l.id));

  const msgs = thread.messages;
  const defaultExpanded = useMemo(() => new Set(msgs.slice(-1).map((m) => m.id)), [msgs]);
  const toggle = (id: string) =>
    setExpandedIds((prev) => {
      const next = new Set(prev);
      const wasDefault = defaultExpanded.has(id);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      // allow collapsing the default-expanded message by tracking explicit collapse
      if (wasDefault && !next.has(id)) next.add(`!${id}`);
      return next;
    });

  const isCollapsedExplicit = (m: Message) => expandedIds.has(`!${m.id}`);
  const expanded = (m: Message) => (defaultExpanded.has(m.id) ? !isCollapsedExplicit(m) : expandedIds.has(m.id));

  const collapsedCount = msgs.filter((m) => !expanded(m)).length;

  return (
    <div className="thread-view">
      <ThreadToolbar thread={thread} />
      <div className="thread-scroll">
        <div className="thread-subject-row">
          <h1 className="thread-subject">{thread.subject || '(no subject)'}</h1>
          {customLabels.map((l) => (
            <span key={l.id} className="label-chip removable" style={{ borderColor: l.color, color: l.color }}>
              {l.name}
              <button aria-label={`Remove label ${l.name}`} onClick={() => applyLabel([thread.id], l.id, false)}>
                <Icon name="close" size={11} />
              </button>
            </span>
          ))}
          <span className="thread-count">{msgs.length} message{msgs.length === 1 ? '' : 's'}</span>
        </div>

        {msgs.map((m) => (
          <MessageCard
            key={m.id}
            m={m}
            thread={thread}
            expanded={expanded(m)}
            onToggle={() => toggle(m.id)}
          />
        ))}

        {collapsedCount > 1 && (
          <button
            className="expand-all"
            onClick={() => setExpandedIds(new Set(msgs.map((m) => m.id)))}
          >
            <Icon name="more" size={16} /> Show {collapsedCount} earlier messages
          </button>
        )}

        <div className="thread-reply-area">
          <InlineReply thread={thread} lastMessage={msgs[msgs.length - 1]} />
        </div>
      </div>
    </div>
  );
}

/* ============================================================
   k3[1m] mail — design system
   ============================================================ */

:root {
  --bg: #f6f8fc;
  --surface: #ffffff;
  --surface-2: #eaf1fb;
  --surface-3: #f0f4f9;
  --text: #1f1f1f;
  --text-2: #444746;
  --text-3: #6b7280;
  --border: #e1e4e8;
  --border-strong: #d3d7dc;
  --accent: #0b57d0;
  --accent-hover: #0842a0;
  --accent-soft: #d3e3fd;
  --accent-contrast: #ffffff;
  --compose-bg: #c2e7ff;
  --compose-text: #001d35;
  --hover: rgba(31, 31, 31, 0.07);
  --active: rgba(31, 31, 31, 0.12);
  --star: #f9ab00;
  --danger: #d93025;
  --snooze: #b06000;
  --shadow-1: 0 1px 2px rgba(60, 64, 67, 0.15), 0 1px 3px 1px rgba(60, 64, 67, 0.08);
  --shadow-2: 0 1px 3px rgba(60, 64, 67, 0.2), 0 4px 8px 3px rgba(60, 64, 67, 0.12);
  --shadow-3: 0 4px 12px rgba(0, 0, 0, 0.22), 0 8px 24px rgba(0, 0, 0, 0.18);
  --row-h: 44px;
  --radius: 16px;
}

[data-theme='dark'] {
  --bg: #131417;
  --surface: #1d2025;
  --surface-2: #2a2e35;
  --surface-3: #23262c;
  --text: #e6e8eb;
  --text-2: #c6cacf;
  --text-3: #9aa0a6;
  --border: #33373e;
  --border-strong: #43484f;
  --accent: #a8c7fa;
  --accent-hover: #c5d9fc;
  --accent-soft: #003a8c;
  --accent-contrast: #062c6b;
  --compose-bg: #2b4a7c;
  --compose-text: #dbe7fd;
  --hover: rgba(230, 232, 235, 0.08);
  --active: rgba(230, 232, 235, 0.14);
  --star: #fdd663;
  --danger: #f28b82;
  --snooze: #e8a13c;
  --shadow-1: 0 1px 2px rgba(0, 0, 0, 0.4), 0 1px 3px 1px rgba(0, 0, 0, 0.3);
  --shadow-2: 0 1px 3px rgba(0, 0, 0, 0.5), 0 4px 8px 3px rgba(0, 0, 0, 0.35);
  --shadow-3: 0 4px 12px rgba(0, 0, 0, 0.55), 0 8px 24px rgba(0, 0, 0, 0.45);
}

[data-density='comfortable'] { --row-h: 52px; }
[data-density='compact'] { --row-h: 36px; }

* { box-sizing: border-box; }

html, body, #root { height: 100%; }

body {
  margin: 0;
  font-family: Roboto, -apple-system, BlinkMacSystemFont, 'Segoe UI', Helvetica, Arial, sans-serif;
  font-size: 14px;
  color: var(--text);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}

button {
  font-family: inherit;
  font-size: inherit;
  color: inherit;
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
}

input, textarea { font-family: inherit; font-size: inherit; color: inherit; }

mark {
  background: rgba(249, 171, 0, 0.35);
  color: inherit;
  border-radius: 2px;
  padding: 0 1px;
}

::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: rgba(128, 134, 139, 0.35); border-radius: 8px; border: 2px solid transparent; background-clip: content-box; }
::-webkit-scrollbar-track { background: transparent; }

.app { display: flex; flex-direction: column; height: 100%; overflow: hidden; }
.main { display: flex; flex: 1; min-height: 0; }
.content {
  flex: 1;
  min-width: 0;
  background: var(--surface);
  border-radius: var(--radius) 0 0 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  margin-right: 16px;
}

/* ---------------- icons & buttons ---------------- */

.icon-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  color: var(--text-2);
  flex: none;
  transition: background 0.12s;
}
.icon-btn:hover { background: var(--hover); }
.icon-btn:active { background: var(--active); }
.icon-btn:disabled { opacity: 0.35; pointer-events: none; }
.icon-btn.small { width: 30px; height: 30px; }
.icon-btn.active-toggle { background: var(--accent-soft); color: var(--accent); }

.icon-btn.spin svg { animation: spin 0.7s linear infinite; }
@keyframes spin { to { transform: rotate(360deg); } }

.btn {
  padding: 8px 16px;
  border-radius: 18px;
  font-weight: 500;
  color: var(--accent);
  transition: background 0.12s;
}
.btn:hover { background: var(--hover); }
.btn.small { padding: 5px 12px; font-size: 13px; }
.btn.primary { background: var(--accent); color: var(--accent-contrast); }
.btn.primary:hover { background: var(--accent-hover); }
.btn.primary:disabled { opacity: 0.4; pointer-events: none; }
.btn.danger-btn { color: var(--danger); border: 1px solid var(--border-strong); }

.link-btn {
  color: var(--accent);
  font-weight: 500;
  padding: 2px 6px;
  border-radius: 4px;
}
.link-btn:hover { background: var(--hover); text-decoration: underline; }

/* ---------------- header ---------------- */

.header {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 64px;
  padding: 6px 12px 6px 8px;
  flex: none;
}
.header-left { display: flex; align-items: center; gap: 4px; min-width: 0; }
.logo { display: flex; align-items: center; gap: 10px; padding: 0 8px 0 4px; user-select: none; }
.logo-text {
  font-size: 21px;
  font-weight: 500;
  letter-spacing: -0.3px;
  color: var(--text-2);
}
.header-right { display: flex; align-items: center; gap: 2px; margin-left: auto; }

/* search */
.search-wrap { position: relative; flex: 1; max-width: 720px; margin: 0 auto; }
.search-bar {
  display: flex;
  align-items: center;
  height: 48px;
  background: var(--surface-2);
  border-radius: 24px;
  padding: 0 8px;
  transition: box-shadow 0.15s, background 0.15s;
}
.search-bar:focus-within { background: var(--surface); box-shadow: var(--shadow-2); }
.search-input {
  flex: 1;
  border: none;
  outline: none;
  background: transparent;
  font-size: 16px;
  color: var(--text);
  min-width: 0;
}
.search-input::placeholder { color: var(--text-3); }

.search-pop { padding: 6px 0; max-height: 380px; overflow-y: auto; }
.search-item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 9px 16px;
  text-align: left;
  color: var(--text-2);
}
.search-item.active { background: var(--hover); }
.search-item-label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.search-pop-empty { padding: 14px 18px; color: var(--text-3); font-size: 13px; }
.search-pop-foot {
  padding: 10px 18px 6px;
  color: var(--text-3);
  font-size: 12px;
  border-top: 1px solid var(--border);
  margin-top: 4px;
}

/* ---------------- popovers & menus ---------------- */

.popover {
  position: absolute;
  top: calc(100% + 6px);
  left: 0;
  z-index: 60;
  background: var(--surface);
  border-radius: 12px;
  box-shadow: var(--shadow-3);
  border: 1px solid var(--border);
  padding: 6px;
  min-width: 180px;
  animation: pop-in 0.12s ease-out;
}
.popover-right { left: auto; right: 0; }
.search-wrap .search-pop { width: 100%; }
@keyframes pop-in {
  from { opacity: 0; transform: translateY(-4px) scale(0.98); }
  to { opacity: 1; transform: none; }
}

.menu-anchor { position: relative; display: inline-flex; }
.menu-pop { min-width: 200px; }
.menu-item {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 8px 12px;
  border-radius: 8px;
  text-align: left;
  color: var(--text-2);
  white-space: nowrap;
}
.menu-item:hover { background: var(--hover); }
.menu-item.danger { color: var(--danger); }
.menu-item.spread { justify-content: space-between; }
.menu-hint { color: var(--text-3); font-size: 12px; }
.menu-sep { height: 1px; background: var(--border); margin: 5px 8px; }
.menu-note { padding: 6px 12px; color: var(--text-3); font-size: 12px; }
.menu-title { padding: 6px 12px 2px; color: var(--text-3); font-size: 12px; font-weight: 500; }
.menu-check { width: 18px; display: inline-flex; justify-content: center; color: var(--accent); }
.menu-custom { display: flex; gap: 8px; padding: 8px 12px; align-items: center; }
.menu-custom input {
  flex: 1;
  min-width: 0;
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  padding: 6px 8px;
  background: var(--surface);
  color-scheme: light dark;
}

/* account */
.account-wrap { position: relative; }
.avatar-btn { border-radius: 50%; padding: 2px; margin-left: 4px; }
.avatar-btn:hover { box-shadow: 0 0 0 4px var(--hover); }
.avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  color: #fff;
  font-weight: 500;
  flex: none;
  user-select: none;
  letter-spacing: 0.3px;
}
.account-pop { padding: 0; overflow: hidden; }
.account-card { display: flex; align-items: center; gap: 14px; padding: 18px 18px 12px; }
.account-name { font-weight: 500; font-size: 15px; }
.account-email { color: var(--text-3); font-size: 13px; }
.account-storage { padding: 0 18px 12px; border-bottom: 1px solid var(--border); }
.storage-bar { height: 6px; border-radius: 3px; background: var(--surface-3); overflow: hidden; }
.storage-fill { height: 100%; border-radius: 3px; background: linear-gradient(90deg, #0b57d0, #7a42d8); }
.storage-text { color: var(--text-3); font-size: 12px; margin-top: 6px; }
.menu-list { padding: 8px; }

/* ---------------- sidebar ---------------- */

.sidebar {
  width: 264px;
  flex: none;
  padding: 10px 12px 16px 8px;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  transition: margin-left 0.18s ease, transform 0.18s ease;
}
.sidebar.collapsed { width: 76px; padding-right: 6px; }
.sidebar.collapsed .nav-label,
.sidebar.collapsed .nav-count,
.sidebar.collapsed .nav-labels-header,
.sidebar.collapsed .sidebar-storage,
.sidebar.collapsed .compose-btn span,
.sidebar.collapsed .label-delete { display: none; }
.sidebar.collapsed .nav-item { justify-content: center; padding: 0; width: 48px; border-radius: 16px; margin: 0 auto; }
.sidebar.collapsed .compose-btn { width: 48px; padding: 0; justify-content: center; border-radius: 16px; }

.drawer-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.4);
  z-index: 80;
}
.sidebar-drawer {
  position: fixed;
  top: 0;
  left: 0;
  bottom: 0;
  z-index: 90;
  background: var(--bg);
  transform: translateX(-105%);
  box-shadow: none;
  padding-top: 20px;
}
.sidebar-drawer.open { transform: none; box-shadow: var(--shadow-3); }

.compose-btn {
  display: flex;
  align-items: center;
  gap: 12px;
  height: 52px;
  padding: 0 20px;
  margin: 4px 0 14px 4px;
  border-radius: 16px;
  background: var(--compose-bg);
  color: var(--compose-text);
  font-weight: 500;
  font-size: 14px;
  box-shadow: none;
  transition: box-shadow 0.15s, transform 0.05s;
  align-self: flex-start;
}
.compose-btn:hover { box-shadow: var(--shadow-2); }
.compose-btn:active { transform: scale(0.98); }

.nav-section { display: flex; flex-direction: column; gap: 1px; }
.nav-item {
  display: flex;
  align-items: center;
  gap: 14px;
  height: 34px;
  padding: 0 14px 0 16px;
  border-radius: 0 18px 18px 0;
  color: var(--text-2);
  text-align: left;
  position: relative;
}
.nav-item:hover { background: var(--hover); }
.nav-item.active { background: var(--accent-soft); color: var(--accent); font-weight: 600; }
.nav-count { margin-left: auto; font-size: 12px; color: var(--text-3); font-weight: 500; }
.nav-item.active .nav-count { color: var(--accent); }
.nav-label { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.nav-labels-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 16px 4px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-3);
}
.label-item { cursor: pointer; }
.label-delete {
  margin-left: auto;
  display: none;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  color: var(--text-3);
}
.label-item:hover .label-delete { display: inline-flex; }
.label-delete:hover { background: var(--active); color: var(--danger); }

.sidebar-storage { margin-top: auto; padding: 18px 16px 4px; }

/* ---------------- toolbar ---------------- */

.toolbar {
  display: flex;
  align-items: center;
  gap: 2px;
  height: 48px;
  padding: 0 10px 0 12px;
  flex: none;
  border-bottom: 1px solid var(--border);
}
.toolbar-sep { width: 1px; height: 22px; background: var(--border-strong); margin: 0 6px; }
.toolbar-right { margin-left: auto; display: flex; align-items: center; gap: 0; }
.pager-text { font-size: 12px; color: var(--text-3); margin: 0 6px; white-space: nowrap; }

.select-wrap { position: relative; display: flex; align-items: center; margin-right: 4px; }
.checkbox {
  width: 20px;
  height: 20px;
  border: 2px solid var(--text-3);
  border-radius: 3px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin: 8px;
  color: #fff;
  transition: background 0.1s, border-color 0.1s;
}
.checkbox.checked { background: var(--accent); border-color: var(--accent); color: var(--accent-contrast); }
[data-theme='dark'] .checkbox.checked { color: #0b57d0; }
.checkbox.indeterminate { background: var(--accent); border-color: var(--accent); color: var(--accent-contrast); }
.checkbox.indeterminate svg { transform: scaleX(1.4) scaleY(0.4); }

/* ---------------- category tabs ---------------- */

.category-tabs {
  display: flex;
  border-bottom: 1px solid var(--border);
  flex: none;
  overflow-x: auto;
}
.category-tab {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 13px 18px 11px;
  color: var(--text-2);
  border-bottom: 3px solid transparent;
  min-width: 160px;
  flex: 1;
  justify-content: flex-start;
  white-space: nowrap;
}
.category-tab:hover { background: var(--hover); }
.category-tab.active { color: var(--accent); border-bottom-color: var(--accent); }
.category-new {
  font-size: 12px;
  font-weight: 500;
  color: var(--accent);
  background: var(--accent-soft);
  border-radius: 10px;
  padding: 2px 8px;
  margin-left: auto;
}
[data-theme='dark'] .category-new { color: #dbe7fd; }

/* ---------------- mail list ---------------- */

.list-pane { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.mail-list { flex: 1; overflow-y: auto; overscroll-behavior: contain; }

.mail-row {
  display: flex;
  align-items: center;
  height: var(--row-h);
  padding-right: 12px;
  border-bottom: 1px solid var(--border);
  cursor: pointer;
  position: relative;
  background: var(--surface);
  color: var(--text-2);
  user-select: none;
}
.mail-row:hover { box-shadow: inset 1px 0 0 var(--border-strong), inset -1px 0 0 var(--border-strong), 0 0 4px rgba(0,0,0,0.12); z-index: 1; }
.mail-row.unread { color: var(--text); }
.mail-row.unread .row-sender,
.mail-row.unread .row-subject,
.mail-row.unread .row-date { font-weight: 700; }
.mail-row.selected { background: var(--accent-soft); }
[data-theme='dark'] .mail-row.selected { color: #dbe7fd; }
.mail-row.cursor { outline: 2px solid var(--accent); outline-offset: -2px; border-radius: 4px; }

.row-cell { display: flex; align-items: center; min-width: 0; }
.row-check { flex: none; opacity: 1; }
.row-star { flex: none; }
.star-btn {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--text-3);
}
.star-btn:hover { background: var(--hover); }
.star-btn.starred { color: var(--star); }

.row-sender {
  flex: 0 0 190px;
  padding: 0 8px 0 4px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.row-sender.draft-sender { color: var(--danger); font-weight: 500; }
.row-count { color: var(--text-3); font-weight: 400; font-size: 12px; }

.row-content {
  flex: 1;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;
  padding-right: 10px;
}
.row-subject { color: var(--text); }
.mail-row:not(.unread) .row-subject { color: var(--text-2); }
.row-dash { color: var(--text-3); }
.row-snippet { color: var(--text-3); }
.row-labels { display: inline-flex; gap: 4px; margin-left: 8px; vertical-align: 1px; }

.label-chip {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  font-size: 11px;
  font-weight: 500;
  border: 1px solid;
  border-radius: 8px;
  padding: 1px 6px;
  background: transparent;
  line-height: 1.5;
}
.label-chip.removable button {
  display: inline-flex;
  color: inherit;
  opacity: 0.7;
}
.label-chip.removable button:hover { opacity: 1; }

.row-meta { flex: none; gap: 8px; color: var(--text-3); }
.row-attach { flex: none; }
.row-date { font-size: 12px; display: inline-flex; align-items: center; gap: 4px; }
.snoozed-date { color: var(--snooze); font-weight: 500; }

.row-actions {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  display: none;
  gap: 0;
  background: var(--surface);
  border-radius: 20px;
  box-shadow: var(--shadow-1);
  padding: 1px 4px;
}
.mail-row.selected .row-actions { background: var(--accent-soft); }
.mail-row:hover .row-actions { display: flex; }
.mail-row:hover .row-meta { visibility: hidden; }

.search-banner, .folder-banner {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 18px;
  font-size: 13px;
  color: var(--text-2);
  background: var(--surface-3);
  border-bottom: 1px solid var(--border);
  flex: none;
}
.folder-banner .link-btn { margin-left: 8px; }

.list-footer {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 18px;
  border-top: 1px solid var(--border);
  color: var(--text-3);
  font-size: 13px;
  flex: none;
}

.empty-state {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 80px 24px;
  color: var(--text-3);
  text-align: center;
}
.empty-title { font-size: 18px; color: var(--text-2); }
.empty-hint { font-size: 13px; max-width: 380px; }

/* ---------------- thread view ---------------- */

.thread-view { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.thread-scroll { flex: 1; overflow-y: auto; padding: 8px 20px 40px; }

.thread-subject-row {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
  padding: 12px 4px 14px;
}
.thread-subject { font-size: 21px; font-weight: 400; margin: 0; color: var(--text); }
.thread-count { color: var(--text-3); font-size: 13px; margin-left: auto; }

.msg-card {
  border: 1px solid var(--border);
  border-radius: 12px;
  margin-bottom: 10px;
  background: var(--surface);
  overflow: hidden;
}
.msg-card.collapsed {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 10px 16px;
  text-align: left;
}
.msg-card.collapsed:hover { box-shadow: var(--shadow-1); }
.msg-collapsed-sender { font-weight: 500; color: var(--text); flex: none; }
.msg-collapsed-sender.unread { font-weight: 700; }
.msg-collapsed-snippet {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-3);
}
.msg-collapsed-date { flex: none; color: var(--text-3); font-size: 12px; }

.msg-head { display: flex; gap: 12px; padding: 14px 16px 6px; cursor: default; align-items: flex-start; }
.msg-head-main { flex: 1; min-width: 0; }
.msg-sender-line { display: flex; align-items: baseline; gap: 8px; flex-wrap: wrap; }
.msg-sender { font-weight: 600; color: var(--text); font-size: 14.5px; }
.msg-you-badge {
  font-size: 11px;
  font-weight: 500;
  color: var(--text-3);
  border: 1px solid var(--border-strong);
  border-radius: 4px;
  padding: 0 4px;
}
.msg-email { color: var(--text-3); font-size: 12.5px; }
.msg-to {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  color: var(--text-3);
  font-size: 12.5px;
  margin-top: 2px;
  padding: 1px 4px;
  margin-left: -4px;
  border-radius: 4px;
}
.msg-to:hover { background: var(--hover); }
.msg-to-caret { transition: transform 0.15s; }
.msg-to-caret.flip { transform: rotate(180deg); }

.msg-details {
  margin: 8px 0 4px;
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px 14px;
  background: var(--surface-3);
}
.msg-details table { border-collapse: collapse; font-size: 12.5px; }
.msg-details td { padding: 3px 14px 3px 0; vertical-align: top; color: var(--text-2); }
.msg-details td:first-child { color: var(--text-3); white-space: nowrap; }
.msg-details a { color: var(--accent); }

.msg-head-side { display: flex; align-items: center; gap: 2px; flex: none; }
.msg-date { color: var(--text-3); font-size: 12px; margin-right: 6px; white-space: nowrap; }

.msg-body {
  padding: 6px 16px 14px 64px;
  font-size: 14px;
  line-height: 1.55;
  color: var(--text);
  overflow-wrap: break-word;
}
.msg-body p { margin: 0 0 10px; }
.msg-body p:last-child { margin-bottom: 0; }
.msg-body ul { margin: 6px 0 12px; padding-left: 24px; }
.msg-body a { color: var(--accent); }
.msg-body code {
  background: var(--surface-3);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 1px 5px;
  font-size: 12.5px;
}

.msg-attach {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 4px 16px 14px 64px;
}
.attach-chip {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  padding: 8px 12px;
  min-width: 220px;
  max-width: 320px;
  text-align: left;
  transition: background 0.12s, box-shadow 0.12s;
}
.attach-chip:hover { background: var(--hover); box-shadow: var(--shadow-1); }
.attach-icon {
  width: 34px;
  height: 34px;
  border-radius: 8px;
  background: var(--accent-soft);
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
}
[data-theme='dark'] .attach-icon { color: #dbe7fd; }
.attach-icon-img { background: #fce8e6; color: #c5221f; }
[data-theme='dark'] .attach-icon-img { background: #5c2b29; color: #f6aea9; }
.attach-info { display: flex; flex-direction: column; min-width: 0; flex: 1; }
.attach-name {
  font-size: 13px;
  font-weight: 500;
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.attach-size { font-size: 12px; color: var(--text-3); }
.attach-dl { color: var(--text-3); flex: none; }
.attach-chip.small { min-width: 0; padding: 4px 8px; gap: 6px; border-radius: 8px; }
.attach-chip.small button { display: inline-flex; color: var(--text-3); border-radius: 50%; padding: 2px; }
.attach-chip.small button:hover { background: var(--active); }

.msg-actions { padding: 0 16px 14px 64px; }
.reply-btns { display: flex; gap: 10px; padding: 4px 0 8px; }
.reply-btns.compact { padding: 0; }
.reply-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--border-strong);
  border-radius: 18px;
  padding: 8px 18px;
  color: var(--text-2);
  font-weight: 500;
  transition: background 0.12s, box-shadow 0.12s;
}
.reply-btn:hover { background: var(--hover); box-shadow: var(--shadow-1); }

.expand-all {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 2px 0 14px 4px;
  padding: 8px 16px;
  border: 1px dashed var(--border-strong);
  border-radius: 12px;
  color: var(--text-3);
  width: calc(100% - 4px);
}
.expand-all:hover { background: var(--hover); color: var(--text-2); }

.thread-reply-area { margin-top: 14px; padding: 0 4px; }

/* ---------------- inline reply ---------------- */

.inline-reply {
  border: 1px solid var(--border-strong);
  border-radius: 12px;
  background: var(--surface);
  box-shadow: var(--shadow-1);
  margin-bottom: 12px;
  overflow: hidden;
}
.inline-reply-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-bottom: 1px solid var(--border);
}
.inline-reply-mode { font-weight: 600; font-size: 13px; }
.inline-reply-to { color: var(--text-3); font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; flex: 1; }

.compose-body {
  padding: 14px 16px;
  min-height: 150px;
  outline: none;
  font-size: 14px;
  line-height: 1.55;
  overflow-y: auto;
  overflow-wrap: break-word;
}
.inline-body { min-height: 100px; }
.compose-body p { margin: 0 0 10px; }
.compose-body a { color: var(--accent); }

.format-bar {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 4px 12px;
  border-top: 1px solid var(--border);
}
.format-sep { width: 1px; height: 18px; background: var(--border-strong); margin: 0 6px; }
.tx-btn { font-weight: 700; font-size: 13px; }
.tx-btn x { font-weight: 400; font-size: 11px; vertical-align: 2px; }

.link-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-top: 1px solid var(--border);
  background: var(--surface-3);
}
.link-bar input {
  flex: 1;
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  padding: 7px 10px;
  outline: none;
  background: var(--surface);
}
.link-bar input:focus { border-color: var(--accent); }

.inline-reply-foot {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 12px;
  border-top: 1px solid var(--border);
}
.inline-discard { margin-left: auto; }

/* ---------------- compose ---------------- */

.compose {
  position: fixed;
  right: 16px;
  bottom: 0;
  width: min(560px, calc(100vw - 32px));
  max-height: min(78vh, 720px);
  display: flex;
  flex-direction: column;
  background: var(--surface);
  border-radius: 14px 14px 0 0;
  box-shadow: var(--shadow-3);
  border: 1px solid var(--border);
  border-bottom: none;
  z-index: 100;
  animation: compose-in 0.16s ease-out;
}
@keyframes compose-in {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: none; }
}

.compose-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 10px 8px 16px;
  background: var(--surface-2);
  border-radius: 14px 14px 0 0;
  flex: none;
}
.compose-title { font-weight: 500; font-size: 13.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.compose-head-actions { display: flex; gap: 2px; }

.compose-fields { flex: none; border-bottom: 1px solid var(--border); }
.compose-from {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 14px 4px 0;
}
.compose-from-email { color: var(--text-3); font-size: 13px; flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

.rcp-row {
  display: flex;
  align-items: flex-start;
  border-bottom: 1px solid var(--border);
  position: relative;
  padding-right: 14px;
}
.rcp-row:last-child { border-bottom: none; }
.rcp-label {
  flex: none;
  width: 62px;
  padding: 9px 0 8px 14px;
  color: var(--text-3);
  font-size: 13px;
}
.rcp-field {
  flex: 1;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 4px;
  padding: 3px 0;
  min-width: 0;
}
.rcp-input {
  flex: 1;
  min-width: 120px;
  border: none;
  outline: none;
  background: transparent;
  padding: 5px 0;
  font-size: 14px;
}
.chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: var(--surface-3);
  border: 1px solid var(--border-strong);
  border-radius: 14px;
  padding: 3px 6px 3px 10px;
  font-size: 13px;
  max-width: 220px;
}
.chip-name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.chip-x {
  display: inline-flex;
  border-radius: 50%;
  padding: 2px;
  color: var(--text-3);
}
.chip-x:hover { background: var(--active); color: var(--danger); }
.rcp-pop { padding: 4px; }
.rcp-pop-name { font-weight: 500; color: var(--text); }
.rcp-pop-email { color: var(--text-3); font-size: 12px; }
.search-item .rcp-pop-email { margin-left: auto; }

.subject-input {
  flex: 1;
  border: none;
  outline: none;
  background: transparent;
  padding: 9px 0;
  font-size: 14px;
  min-width: 0;
}

.compose .compose-body { flex: 1; min-height: 190px; max-height: 46vh; }

.compose-attach {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 8px 14px;
  border-top: 1px solid var(--border);
}

.compose-foot {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 8px 12px;
  border-top: 1px solid var(--border);
  flex: none;
}
.compose-foot-spacer { flex: 1; }
.send-btn {
  background: var(--accent);
  color: var(--accent-contrast);
  font-weight: 500;
  border-radius: 18px;
  padding: 9px 24px;
  margin-right: 8px;
  transition: background 0.12s, box-shadow 0.12s;
}
.send-btn:hover { background: var(--accent-hover); box-shadow: var(--shadow-1); }

.emoji-pop { padding: 8px; }
.emoji-grid { display: grid; grid-template-columns: repeat(8, 1fr); gap: 2px; }
.emoji-btn { font-size: 19px; padding: 4px; border-radius: 8px; line-height: 1.2; }
.emoji-btn:hover { background: var(--hover); }

.compose-min {
  position: fixed;
  right: 16px;
  bottom: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  gap: 10px;
  width: 260px;
  padding: 12px 14px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-bottom: none;
  border-radius: 12px 12px 0 0;
  box-shadow: var(--shadow-2);
  color: var(--text-2);
  font-weight: 500;
}
.compose-min-title { flex: 1; text-align: left; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

/* ---------------- toasts ---------------- */

.toasts {
  position: fixed;
  left: 20px;
  bottom: 20px;
  z-index: 200;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.toast {
  display: flex;
  align-items: center;
  gap: 6px;
  background: #303134;
  color: #e8eaed;
  border-radius: 8px;
  padding: 10px 10px 10px 16px;
  box-shadow: var(--shadow-3);
  font-size: 13.5px;
  max-width: min(420px, calc(100vw - 40px));
  animation: toast-in 0.18s ease-out;
}
[data-theme='dark'] .toast { background: #e8eaed; color: #1f1f1f; }
@keyframes toast-in {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: none; }
}
.toast-msg { flex: 1; }
.toast-action {
  color: #a8c7fa;
  font-weight: 600;
  padding: 6px 10px;
  border-radius: 6px;
  white-space: nowrap;
}
[data-theme='dark'] .toast-action { color: #0b57d0; }
.toast-action:hover { background: rgba(168, 199, 250, 0.12); }
.toast-close { color: inherit; opacity: 0.7; font-size: 16px; padding: 2px 8px; border-radius: 6px; }
.toast-close:hover { opacity: 1; background: rgba(255, 255, 255, 0.1); }

/* ---------------- dialogs ---------------- */

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(0, 0, 0, 0.45);
  z-index: 300;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: fade-in 0.14s ease-out;
}
@keyframes fade-in { from { opacity: 0; } }
.dialog {
  background: var(--surface);
  border-radius: 18px;
  box-shadow: var(--shadow-3);
  width: 100%;
  max-width: 480px;
  max-height: 85vh;
  display: flex;
  flex-direction: column;
  outline: none;
  animation: pop-in 0.15s ease-out;
}
.dialog-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 18px 14px 8px 24px;
}
.dialog-head h2 { margin: 0; font-size: 19px; font-weight: 500; }
.dialog-body { padding: 8px 24px 22px; overflow-y: auto; }
.dialog-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 18px; }

.shortcuts-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 4px 28px; }
.shortcuts-grid > div:first-child { grid-column: 1 / -1; }
.shortcuts-group { font-size: 13px; color: var(--text-3); font-weight: 500; margin: 12px 0 6px; }
.shortcuts-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.shortcuts-table td { padding: 4px 8px 4px 0; color: var(--text-2); }
.shortcuts-table td:first-child { white-space: nowrap; width: 1%; }
kbd {
  background: var(--surface-3);
  border: 1px solid var(--border-strong);
  border-bottom-width: 2px;
  border-radius: 5px;
  padding: 1px 7px;
  font-family: inherit;
  font-size: 12px;
  color: var(--text);
}

.settings-section { margin-top: 18px; }
.settings-label { font-size: 13px; font-weight: 500; color: var(--text-2); margin-bottom: 8px; }
.settings-hint { font-size: 12.5px; color: var(--text-3); max-width: 300px; }
.settings-account { font-size: 13.5px; color: var(--text-2); }
.settings-danger { display: flex; align-items: center; justify-content: space-between; gap: 16px; border-top: 1px solid var(--border); padding-top: 18px; }

.segmented { display: flex; gap: 8px; }
.segment {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  padding: 8px 16px;
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  color: var(--text-2);
}
.segment:hover { background: var(--hover); }
.segment.active { border-color: var(--accent); color: var(--accent); background: var(--accent-soft); font-weight: 500; }
[data-theme='dark'] .segment.active { color: #dbe7fd; }

.sig-input, .text-input {
  width: 100%;
  border: 1px solid var(--border-strong);
  border-radius: 10px;
  padding: 10px 12px;
  outline: none;
  background: var(--surface);
  resize: vertical;
}
.sig-input:focus, .text-input:focus { border-color: var(--accent); box-shadow: 0 0 0 2px var(--accent-soft); }

.color-row { display: flex; gap: 10px; flex-wrap: wrap; }
.color-dot {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: transform 0.1s;
}
.color-dot:hover { transform: scale(1.12); }
.color-dot.active { box-shadow: 0 0 0 3px var(--surface), 0 0 0 5px currentColor; }

/* ---------------- responsive ---------------- */

@media (max-width: 1100px) {
  .row-sender { flex-basis: 150px; }
}

@media (max-width: 900px) {
  .content { margin-right: 0; border-radius: 0; }
  .header { padding-right: 8px; }
  .category-tab { min-width: 0; padding: 12px 14px 10px; }
  .category-tab-label { display: none; }
  .category-tab.active .category-tab-label { display: inline; }
  .msg-body, .msg-attach, .msg-actions { padding-left: 16px; }
  .thread-scroll { padding: 4px 12px 40px; }
}

@media (max-width: 700px) {
  .logo-text { display: none; }
  .header-right .icon-btn[aria-label='Keyboard shortcuts'] { display: none; }
  .search-bar { height: 44px; }
  .thread-subject { font-size: 18px; }
  .msg-head { flex-wrap: wrap; }
  .msg-head-side { margin-left: auto; }
  .msg-date { display: none; }
  .compose {
    right: 0;
    width: 100vw;
    max-height: 92vh;
    height: 92vh;
    border-radius: 14px 14px 0 0;
  }
  .compose .compose-body { max-height: none; flex: 1; }
  .shortcuts-grid { grid-template-columns: 1fr; }
  .row-sender { flex-basis: 120px; }
  .row-labels { display: none; }
  .pager-text { display: none; }
}

@media (max-width: 520px) {
  .row-sender { flex-basis: 96px; font-size: 13px; }
  .row-snippet { display: none; }
  .header { gap: 2px; }
  .header-right .icon-btn[aria-label='Toggle theme'] { display: none; }
  .toolbar .pager-text { display: none; }
  .icon-btn { width: 36px; height: 36px; }
  .empty-state { padding: 48px 16px; }
}

/* ---------------- print ---------------- */

@media print {
  .header, .sidebar, .toolbar, .thread-reply-area, .compose, .compose-min,
  .toasts, .dialog-backdrop, .expand-all, .msg-head-side, .category-tabs { display: none !important; }
  .content { margin: 0; border-radius: 0; }
  .msg-card { border: none; }
  .msg-card.collapsed { display: none; }
  body { background: #fff; }
}

