input.command:
dev-browser --headless <<'EOF'
const page = await browser.getPage("main");
const errors = [];
page.on("pageerror", (err) => errors.push(String(err)));
await page.goto("http://localhost:9211");
await page.waitForTimeout(1200);
// compose flow
await page.getByRole("button", { name: "Compose" }).click();
await page.waitForTimeout(400);
await page.locator(".rcp-input").first().fill("may");
await page.waitForTimeout(300);
await page.keyboard.press("Enter");           // pick Maya suggestion
await page.locator(".subject-input").fill("Rollout checklist — first pass");
await page.locator(".compose-body").fill("Here is the checklist you asked for. Two items need your sign-off.");
const shot1 = await saveScreenshot(await page.screenshot(), "compose.png");
await page.keyboard.press("Escape");          // close -> saves draft
await page.waitForTimeout(500);
const toast1 = await page.locator(".toast").allTextContents();
// reopen from Drafts
await page.getByRole("button", { name: /^Drafts/ }).click();
await page.waitForTimeout(400);
const draftRows = await page.locator(".mail-row").count();
await page.locator(".mail-row .row-subject", { hasText: "Rollout checklist" }).first().click();
await page.waitForTimeout(400);
await page.keyboard.press("Escape");          // close compose again (focus not inside) 
await page.waitForTimeout(200);
const shot2 = await saveScreenshot(await page.screenshot(), "draft-reopen.png");
console.log(JSON.stringify({ toast1, draftRows, errors, shot1, shot2 }, null, 2));
EOF

